PROJECT = Path(r"C:\PhoCap")
APP = PROJECT / "app"

MAIN = APP / "main.py"
MENU = APP / "templates" / "partials" / "dropdown_menu_v1.html"
ROUTER = APP / "routers" / "data_tools.py"
TEMPLATE = APP / "templates" / "data_tools" / "survey_cleanup.html"

EXPORTS = PROJECT / "exports"
STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = EXPORTS / f"backup_bai_13b_10_v3_18a_{STAMP}"
MANIFEST = BACKUP / "manifest.json"

MAIN_IMPORT_MARK = "BAI_13B_10_V3_18A_DATA_TOOLS_IMPORT"
MAIN_INCLUDE_MARK = "BAI_13B_10_V3_18A_DATA_TOOLS_INCLUDE"
MENU_MARK = "BAI_13B_10_V3_18A_DATA_TOOLS_MENU"

ROUTER_CODE = base64.b64decode(
    ""
).decode("utf-8")

TEMPLATE_CODE = base64.b64decode(
    ""
).decode("utf-8")

MENU_BLOCK = base64.b64decode(
    ""
).decode("utf-8")


def read_text(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)

    paths = [MAIN, MENU, ROUTER, TEMPLATE]
    manifest: list[dict] = []

    for path in paths:
        existed = path.exists()
        manifest.append(
            {
                "path": str(path.relative_to(PROJECT)),
                "existed": existed,
            }
        )

        if existed:
            dst = BACKUP / path.relative_to(PROJECT)
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dst)

    MANIFEST.write_text(
        json.dumps(
            manifest,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    return manifest


def restore_files(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]

        if item["existed"]:
            source = BACKUP / item["path"]
            if source.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target)
        elif target.exists() and target.is_file():
            target.unlink()


def patch_main(text: str) -> str:
    if MAIN_IMPORT_MARK not in text:
        anchor = "from app.routers.schools import router as schools_router"
        if anchor not in text:
            raise RuntimeError(
                "main.py không có import schools_router. "
                "Dừng để tránh chèn router sai vị trí."
            )

        text = text.replace(
            anchor,
            anchor
            + "\n# === "
            + MAIN_IMPORT_MARK
            + " ==="
            + "\nfrom app.routers.data_tools "
            + "import router as data_tools_router",
            1,
        )

    if MAIN_INCLUDE_MARK not in text:
        anchor = "app.include_router(schools_router)"
        if anchor not in text:
            raise RuntimeError(
                "main.py không có app.include_router(schools_router)."
            )

        text = text.replace(
            anchor,
            anchor
            + "\n# === "
            + MAIN_INCLUDE_MARK
            + " ==="
            + "\napp.include_router(data_tools_router)",
            1,
        )

    return text


def find_matching_div_close(
    segment: str,
    open_pos: int,
) -> int:
    token_re = re.compile(
        r"<div\b[^>]*>|</div\s*>",
        flags=re.I | re.S,
    )

    depth = 0
    started = False

    for match in token_re.finditer(segment, open_pos):
        token = match.group(0).lower()

        if token.startswith("<div"):
            depth += 1
            started = True
            continue

        if token.startswith("</div"):
            depth -= 1
            if started and depth == 0:
                return match.start()

    raise RuntimeError(
        "Không tìm được thẻ đóng của pc-dropdown."
    )


def patch_menu(text: str) -> str:
    if MENU_MARK in text:
        return text

    admin_patterns = [
        "{% if menu_role in ['ADMIN', 'SO'] %}",
        '{% if menu_role in ["ADMIN", "SO"] %}',
    ]
    start = -1

    for pattern in admin_patterns:
        start = text.find(pattern)
        if start >= 0:
            break

    if start < 0:
        raise RuntimeError(
            "Không tìm thấy nhánh menu ADMIN/SỞ."
        )

    end = text.find(
        "{% elif menu_role == 'XA' %}",
        start,
    )
    if end < 0:
        end = text.find(
            '{% elif menu_role == "XA" %}',
            start,
        )

    if end < 0:
        raise RuntimeError(
            "Không tìm thấy điểm kết thúc nhánh ADMIN/SỞ."
        )

    segment = text[start:end]

    if "1.2. Đơn vị hành chính" not in segment:
        raise RuntimeError(
            "Nhánh ADMIN/SỞ thiếu nhóm 1.2. Đơn vị hành chính."
        )

    dropdown_match = re.search(
        r'<div\s+class=["\'][^"\']*\bpc-dropdown\b[^"\']*["\'][^>]*>',
        segment,
        flags=re.I | re.S,
    )

    if dropdown_match is None:
        raise RuntimeError(
            "Không tìm thấy pc-dropdown của menu Danh mục."
        )

    close_pos = find_matching_div_close(
        segment,
        dropdown_match.start(),
    )

    patched_segment = (
        segment[:close_pos]
        + MENU_BLOCK
        + segment[close_pos:]
    )

    return text[:start] + patched_segment + text[end:]


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def verify() -> None:
    for path in (MAIN, ROUTER):
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(path)],
            cwd=PROJECT,
            check=True,
        )

    from jinja2 import Environment, FileSystemLoader

    env = Environment(
        loader=FileSystemLoader(str(APP / "templates"))
    )
    env.get_template("partials/dropdown_menu_v1.html")
    env.get_template("data_tools/survey_cleanup.html")

    main_text = read_text(MAIN)
    menu_text = read_text(MENU)
    router_text = read_text(ROUTER)
    tpl_text = read_text(TEMPLATE)

    for item in (
        MAIN_IMPORT_MARK,
        MAIN_INCLUDE_MARK,
        "data_tools_router",
    ):
        if item not in main_text:
            raise RuntimeError(
                f"Kiểm tra main.py chưa đạt: {item}"
            )

    for item in (
        MENU_MARK,
        "1.3. Công cụ dữ liệu",
        "1.3.1. Dọn dẹp dữ liệu điều tra",
        "/cong-cu-du-lieu/don-du-lieu-dieu-tra",
    ):
        if item not in menu_text:
            raise RuntimeError(
                f"Kiểm tra menu chưa đạt: {item}"
            )

    for item in (
        'prefix="/cong-cu-du-lieu"',
        '"/don-du-lieu-dieu-tra"',
        "PRAGMA query_only = ON",
        "def _inventory",
        "households_shared",
    ):
        if item not in router_text:
            raise RuntimeError(
                f"Kiểm tra router chưa đạt: {item}"
            )

    for item in (
        "Giai đoạn V3.18A chỉ",
        "DỌN DỮ LIỆU THỬ NGHIỆM",
        "CHƯA MỞ",
        "Dữ liệu hệ thống sẽ được bảo toàn",
    ):
        if item not in tpl_text:
            raise RuntimeError(
                f"Kiểm tra template chưa đạt: {item}"
            )


